1	// In-process, time bounded lease registry with append-only log persistence.
2	// Time only moves when the injected clock moves; nothing expires on its own.
3	// Tokens are derived from the injected clock as well, never from wall time.
4	
5	import fs from 'node:fs';
6	
7	const LOG_VERSION = 1;
8	
9	export class LeaseTakenError extends Error {
10	  constructor(resource, holder) {
11	    super(`lease for resource ${String(resource)} is already held`);
12	    this.name = 'LeaseTakenError';
13	    this.code = LeaseTakenError.code;
14	    this.resource = resource;
15	    this.holder = holder ?? null;
16	  }
17	}
18	LeaseTakenError.code = 'LEASE_TAKEN';
19	
20	export class LogFileError extends Error {
21	  constructor(message, cause) {
22	    super(message);
23	    this.name = 'LogFileError';
24	    this.code = LogFileError.code;
25	    this.cause = cause ?? null;
26	  }
27	}
28	LogFileError.code = 'LOG_FILE_ERROR';
29	
30	// Binary min-heap ordered by (expiresAt, insertion order). Every live lease
31	// has a node in the queue; renewals push a fresh node and retire the old one,
32	// so reclaiming expired leases only walks entries that are actually due
33	// instead of scanning the whole table.
34	class ExpiryQueue {
35	  constructor() {
36	    this.nodes = [];
37	  }
38	
39	  get size() {
40	    return this.nodes.length;
41	  }
42	
43	  push(node) {
44	    const nodes = this.nodes;
45	    nodes.push(node);
46	    let i = nodes.length - 1;
47	    while (i > 0) {
48	      const parent = (i - 1) >> 1;
49	      if (expiresBefore(nodes[i], nodes[parent])) {
50	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
51	        i = parent;
52	      } else {
53	        break;
54	      }
55	    }
56	  }
57	
58	  peek() {
59	    return this.nodes[0];
60	  }
61	
62	  pop() {
63	    const nodes = this.nodes;
64	    const top = nodes[0];
65	    const last = nodes.pop();
66	    if (nodes.length > 0) {
67	      nodes[0] = last;
68	      let i = 0;
69	      for (;;) {
70	        const left = i * 2 + 1;
71	        const right = left + 1;
72	        let next = i;
73	        if (left < nodes.length && expiresBefore(nodes[left], nodes[next])) {
74	          next = left;
75	        }
76	        if (right < nodes.length && expiresBefore(nodes[right], nodes[next])) {
77	          next = right;
78	        }
79	        if (next === i) {
80	          break;
81	        }
82	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
83	        i = next;
84	      }
85	    }
86	    return top;
87	  }
88	}
89	
90	function expiresBefore(a, b) {
91	  if (a.expiresAt !== b.expiresAt) {
92	    return a.expiresAt < b.expiresAt;
93	  }
94	  return a.order < b.order;
95	}
96	
97	let registrySequence = 0;
98	
99	export function createRegistry({ ttlMs, clock = Date.now, logPath = null } = {}) {
100	  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
101	    throw new TypeError('ttlMs must be a positive finite number');
102	  }
103	  if (typeof clock !== 'function') {
104	    throw new TypeError('clock must be a function');
105	  }
106	
107	  const defaultTtlMs = ttlMs;
108	  // resource -> FIFO array of queue positions. A group request listing the
109	  // same resource twice occupies two consecutive positions in that queue.
110	  const waitQueues = new Map();
111	  // requestId -> group, while the request is still queued.
112	  const pendingGroups = new Map();
113	  // token -> { resource, holder, expiresAt, ttlMs, legacy, heapSeq }
114	  const leases = new Map();
115	  // Every token this instance knows about, including replayed credentials
116	  // that were already released or reclaimed, so a freshly minted token can
117	  // never reuse a dead credential's string.
118	  const knownTokens = new Set();
119	  // resource -> tokens currently occupying it. Usually one entry; an atomic
120	  // group listing one resource several times holds one credential per
121	  // occurrence, all belonging to the same request.
122	  const slots = new Map();
123	  const expiryQueue = new ExpiryQueue();
124	
125	  const counters = {
126	    granted: 0,
127	    renewed: 0,
128	    released: 0,
129	    reclaimed: 0,
130	  };
131	
132	  // Per-instance identity makes tokens unique across registries living in the
133	  // same process; one instance can never present a token another owns.
134	  registrySequence += 1;
135	  const registryId = registrySequence;
136	  let tokenSequence = 0;
137	  let queueOrder = 0;
138	  let requestSequence = 0;
139	  let batchSequence = 0;
140	
141	  function mintToken(now, seq = tokenSequence) {
142	    // Pure candidate: nothing is committed until the event is on disk, so a
143	    // failed append rolls all the way back. Pids and instance ids can coincide
144	    // after a restart, so skip any sequence that collides with a credential
145	    // reconstructed from the log. The caller threads the sequence through when
146	    // it mints several tokens for one atomic write.
147	    let token;
148	    do {
149	      seq += 1;
150	      token = `lease-${process.pid}-${registryId}-${seq}-${now.toString(36)}`;
151	    } while (knownTokens.has(token));
152	    return { token, seq };
153	  }
154	
155	  function enqueue(token, lease) {
156	    expiryQueue.push({
157	      token,
158	      expiresAt: lease.expiresAt,
159	      heapSeq: lease.heapSeq,
160	      order: queueOrder++,
161	    });
162	  }
163	
164	  function isLive(lease, now) {
165	    return lease !== undefined && lease.expiresAt > now;
166	  }
167	
168	  function getSlots(resource) {
169	    let list = slots.get(resource);
170	    if (list === undefined) {
171	      list = [];
172	      slots.set(resource, list);
173	    }
174	    return list;
175	  }
176	
177	  function addSlot(resource, token) {
178	    getSlots(resource).push(token);
179	  }
180	
181	  function removeSlot(resource, token) {
182	    const list = slots.get(resource);
183	    if (list === undefined) {
184	      return false;
185	    }
186	    const index = list.indexOf(token);
187	    if (index === -1) {
188	      return false;
189	    }
190	    list.splice(index, 1);
191	    if (list.length === 0) {
192	      slots.delete(resource);
193	    }
194	    return true;
195	  }
196	
197	  // Drop expired-but-unswept credentials from a resource that is about to be
198	  // granted: the resource is free, and a retaken lease must never be reported
199	  // as reclaimed later. Mirrors the single-resource retake rule.
200	  function dropStaleSlots(resource, now) {
201	    const list = slots.get(resource);
202	    if (list === undefined) {
203	      return;
204	    }
205	    for (let i = list.length - 1; i >= 0; i -= 1) {
206	      const token = list[i];
207	      if (!isLive(leases.get(token), now)) {
208	        leases.delete(token);
209	        list.splice(i, 1);
210	      }
211	    }
212	    if (list.length === 0) {
213	      slots.delete(resource);
214	    }
215	  }
216	
217	  function liveSlotCount(resource, now) {
218	    const list = slots.get(resource);
219	    if (list === undefined) {
220	      return 0;
221	    }
222	    let live = 0;
223	    for (const token of list) {
224	      if (isLive(leases.get(token), now)) {
225	        live += 1;
226	      }
227	    }
228	    return live;
229	  }
230	
231	  function liveHolder(resource, now) {
232	    const list = slots.get(resource);
233	    if (list === undefined) {
234	      return null;
235	    }
236	    for (const token of list) {
237	      const lease = leases.get(token);
238	      if (isLive(lease, now)) {
239	        return lease.holder;
240	      }
241	    }
242	    return null;
243	  }
244	
245	  function appendEvents(events) {
246	    if (logPath === null) {
247	      return;
248	    }
249	    // One write for the whole batch: an operation that frees resources and
250	    // wakes requests either lands completely or not at all.
251	    let text = '';
252	    for (const event of events) {
253	      text += `${JSON.stringify(event)}\n`;
254	    }
255	    try {
256	      fs.appendFileSync(logPath, text);
257	    } catch (cause) {
258	      throw new LogFileError(
259	        `failed to append to lease log at ${logPath}`,
260	        cause,
261	      );
262	    }
263	  }
264	
265	  function appendEvent(event) {
266	    appendEvents([event]);
267	  }
268	
269	  function detachGroup(group) {
270	    for (const position of group.positions) {
271	      const queue = waitQueues.get(position.resource);
272	      if (queue === undefined) {
273	        continue;
274	      }
275	      const index = queue.indexOf(position);
276	      if (index !== -1) {
277	        queue.splice(index, 1);
278	        if (queue.length === 0) {
279	          waitQueues.delete(position.resource);
280	        }
281	      }
282	    }
283	    pendingGroups.delete(group.requestId);
284	  }
285	
286	  // A queued request gives up once the clock reaches its deadline and is
287	  // never woken afterwards. Dropping it moves no counter and no ownership.
288	  function purgeExpiredWaiters(now) {
289	    const dead = [];
290	    for (const group of pendingGroups.values()) {
291	      if (group.deadline <= now) {
292	        dead.push(group);
293	      }
294	    }
295	    for (const group of dead) {
296	      detachGroup(group);
297	      group.ticket.status = 'expired';
298	    }
299	  }
300	
301	  function enqueueGroup(resources, ttlList, holder, now, waitMs, single) {
302	    requestSequence += 1;
303	    const requestId = `wait-${registryId}-${requestSequence}`;
304	    const ticket = single
305	      // Exact baseline shape for single-resource callers.
306	      ? { status: 'waiting', resource: resources[0], holder, waitId: requestId }
307	      : { status: 'waiting', resources: [...resources], holder, waitId: requestId };
308	    const group = {
309	      requestId,
310	      arrival: requestSequence,
311	      holder,
312	      deadline: now + waitMs,
313	      single,
314	      ticket,
315	      positions: [],
316	    };
317	    // One position per listed occurrence, pushed onto each resource's queue
318	    // in the given order. Positions of one request land consecutively, so a
319	    // repeated resource lines up as many times as it was listed.
320	    resources.forEach((resource, index) => {
321	      const position = {
322	        group,
323	        resource,
324	        ttlMs: ttlList[index],
325	        granted: false,
326	        token: null,
327	        expiresAt: null,
328	      };
329	      group.positions.push(position);
330	      let queue = waitQueues.get(resource);
331	      if (queue === undefined) {
332	        queue = [];
333	        waitQueues.set(resource, queue);
334	      }
335	      queue.push(position);
336	    });
337	    pendingGroups.set(requestId, group);
338	    return group;
339	  }
340	
341	  // Plan every grant one request needs (one per still-ungranted position),
342	  // touching no state. The caller commits only after all events are on disk.
343	  // batchId ties the credentials of one atomic batch together for replay.
344	  function planGroupGrants(group, now, seqCursor) {
345	    const batchId = nextBatchId();
346	    const grants = [];
347	    let seq = seqCursor;
348	    for (const position of group.positions) {
349	      if (position.granted) {
350	        continue;
351	      }
352	      const minted = mintToken(now, seq);
353	      seq = minted.seq;
354	      const expiresAt = now + position.ttlMs;
355	      grants.push({
356	        position,
357	        group,
358	        resource: position.resource,
359	        holder: group.holder,
360	        ttlMs: position.ttlMs,
361	        token: minted.token,
362	        seq: minted.seq,
363	        expiresAt,
364	        event: {
365	          v: LOG_VERSION,
366	          type: 'acquire',
367	          at: now,
368	          token: minted.token,
369	          resource: position.resource,
370	          holder: group.holder,
371	          ttlMs: position.ttlMs,
372	          expiresAt,
373	          requestId: group.requestId,
374	          batch: batchId,
375	        },
376	      });
377	    }
378	    return { group, grants, seq, batchId };
379	  }
380	
381	  function applyPlannedGrants(plan, now) {
382	    for (const grant of plan.grants) {
383	      tokenSequence = grant.seq;
384	      knownTokens.add(grant.token);
385	      const lease = {
386	        resource: grant.resource,
387	        holder: grant.holder,
388	        expiresAt: grant.expiresAt,
389	        ttlMs: grant.ttlMs,
390	        legacy: false,
391	        heapSeq: 0,
392	        batch: plan.batchId,
393	      };
394	      leases.set(grant.token, lease);
395	      dropStaleSlots(grant.resource, now);
396	      addSlot(grant.resource, grant.token);
397	      enqueue(grant.token, lease);
398	      counters.granted += 1;
399	
400	      grant.position.token = grant.token;
401	      grant.position.expiresAt = grant.expiresAt;
402	      grant.position.granted = true;
403	    }
404	
405	    // The batch holds everything it asked for; it leaves every queue at once.
406	    const { group } = plan;
407	    const { ticket } = group;
408	    detachGroup(group);
409	    ticket.status = 'granted';
410	    const granted = group.positions.map((position) => ({
411	      resource: position.resource,
412	      holder: group.holder,
413	      token: position.token,
414	      expiresAt: position.expiresAt,
415	    }));
416	    if (group.single) {
417	      ticket.token = granted[0].token;
418	      ticket.expiresAt = granted[0].expiresAt;
419	    } else {
420	      // One credential per listed occurrence, each with its own expiry.
421	      ticket.leases = granted;
422	      // Aliases for callers that read the batch outcome as a flat list.
423	      ticket.results = granted;
424	    }
425	  }
426	
427	  function positionPlanned(plans, position) {
428	    return plans.some((plan) =>
429	      plan.grants.some((grant) => grant.position === position));
430	  }
431	
432	  // A queued request is fillable exactly when every position reaches the
433	  // front of its resource's queue and that resource is free once the
434	  // triggering event is applied. Only live credentials occupy: an expired
435	  // but unswept lease is already gone, while a surviving twin of a released
436	  // duplicate credential keeps the resource held.
437	  function groupFillable(group, plans, freedLiveCount, now) {
438	    for (const position of group.positions) {
439	      if (position.granted) {
440	        continue;
441	      }
442	      const queue = waitQueues.get(position.resource);
443	      if (queue === undefined) {
444	        return false;
445	      }
446	      const index = queue.indexOf(position);
447	      for (let i = 0; i < index; i += 1) {
448	        const ahead = queue[i];
449	        if (ahead.group === group) {
450	          // Own repeated listing: its positions are granted together.
451	          continue;
452	        }
453	        if (positionPlanned(plans, ahead)) {
454	          continue;
455	        }
456	        return false;
457	      }
458	      // A release vacates a live credential; a sweep only removes leases
459	      // that were already expired, so it frees no live occupancy here.
460	      let occupied = Math.max(
461	        0,
462	        liveSlotCount(position.resource, now)
463	          - (freedLiveCount.get(position.resource) ?? 0),
464	      );
465	      for (const plan of plans) {
466	        if (plan.group === group) {
467	          continue;
468	        }
469	        for (const grant of plan.grants) {
470	          if (grant.resource === position.resource) {
471	            occupied += 1;
472	          }
473	        }
474	      }
475	      if (occupied > 0) {
476	        return false;
477	      }
478	    }
479	    return true;
480	  }
481	
482	  // Grant every queued request whose resources become available through the
483	  // given freeing event, cascading across resources and queues. Entries are
484	  // { resource, live }: a release vacates a live credential, a reclaim only
485	  // removes one that had already expired. Everything planned rides in the
486	  // triggering log write.
487	  function planWakeups(freedEntries, now) {
488	    const freedLiveCount = new Map();
489	    for (const entry of freedEntries) {
490	      if (entry.live) {
491	        freedLiveCount.set(
492	          entry.resource,
493	          (freedLiveCount.get(entry.resource) ?? 0) + 1,
494	        );
495	      }
496	    }
497	    const plans = [];
498	    let seq = tokenSequence;
499	    for (;;) {
500	      // Candidates are picked strictly by arrival order: the earliest
501	      // pending request whose batch is now complete wins, so no resource's
502	      // queue can jump ahead of an earlier request.
503	      let next = null;
504	      for (const group of pendingGroups.values()) {
505	        if (plans.some((plan) => plan.group === group)) {
506	          continue;
507	        }
508	        if (!groupFillable(group, plans, freedLiveCount, now)) {
509	          continue;
510	        }
511	        if (next === null || group.arrival < next.arrival) {
512	          next = group;
513	        }
514	      }
515	      if (next === null) {
516	        break;
517	      }
518	      const plan = planGroupGrants(next, now, seq);
519	      seq = plan.seq;
520	      plans.push(plan);
521	    }
522	    return plans;
523	  }
524	
525	  function nextBatchId() {
526	    batchSequence += 1;
527	    return `batch-${registryId}-${batchSequence}`;
528	  }
529	
530	  // Resolve the ttl argument into one positive finite ttl per occurrence.
531	  function resolveTtls(resources, ttlMs) {
532	    if (ttlMs === undefined) {
533	      return resources.map(() => defaultTtlMs);
534	    }
535	    if (Array.isArray(ttlMs)) {
536	      if (ttlMs.length !== resources.length) {
537	        throw new TypeError('ttlMs must match the resources list length');
538	      }
539	      return ttlMs.map((value) => {
540	        if (!Number.isFinite(value) || value <= 0) {
541	          throw new TypeError('ttlMs must be a positive finite number');
542	        }
543	        return value;
544	      });
545	    }
546	    if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
547	      throw new TypeError('ttlMs must be a positive finite number');
548	    }
549	    return resources.map(() => ttlMs);
550	  }
551	
552	  // Persist and commit one credential per listed occurrence, all in a single
553	  // log write. A failed write leaves every resource exactly as before.
554	  function commitDirectGrants(resources, ttlList, holder, now) {
555	    const batchId = nextBatchId();
556	    const events = [];
557	    const grants = [];
558	    let seq = tokenSequence;
559	    resources.forEach((resource, index) => {
560	      const ttlMsValue = ttlList[index];
561	      const minted = mintToken(now, seq);
562	      seq = minted.seq;
563	      const expiresAt = now + ttlMsValue;
564	      events.push({
565	        v: LOG_VERSION,
566	        type: 'acquire',
567	        at: now,
568	        token: minted.token,
569	        resource,
570	        holder,
571	        ttlMs: ttlMsValue,
572	        expiresAt,
573	        batch: batchId,
574	      });
575	      grants.push({ resource, ttlMs: ttlMsValue, token: minted.token, expiresAt });
576	    });
577	    appendEvents(events);
578	
579	    tokenSequence = seq;
580	    const result = [];
581	    for (const grant of grants) {
582	      knownTokens.add(grant.token);
583	      const lease = {
584	        resource: grant.resource,
585	        holder,
586	        expiresAt: grant.expiresAt,
587	        ttlMs: grant.ttlMs,
588	        legacy: false,
589	        heapSeq: 0,
590	        batch: batchId,
591	      };
592	      leases.set(grant.token, lease);
593	      dropStaleSlots(grant.resource, now);
594	      addSlot(grant.resource, grant.token);
595	      enqueue(grant.token, lease);
596	      counters.granted += 1;
597	      result.push({
598	        resource: grant.resource,
599	        holder,
600	        token: grant.token,
601	        expiresAt: grant.expiresAt,
602	      });
603	    }
604	    return result;
605	  }
606	
607	  // Atomic multi-resource acquisition. Every listed occurrence gets its own
608	  // credential and independent expiry; either all of them are held, or none
609	  // are (the whole request queues instead). ttlMs may be one number or one
610	  // ttl per listed resource.
611	  function acquireAll(resources, holder, ttlMs = undefined, waitMs = undefined) {
612	    if (!Array.isArray(resources) || resources.length === 0) {
613	      throw new TypeError('resources must be a non-empty array');
614	    }
615	    const ttlList = resolveTtls(resources, ttlMs);
616	    const wantsWait = validateWait(waitMs);
617	    const now = clock();
618	    purgeExpiredWaiters(now);
619	
620	    // Earlier waiters keep their place, and any live lease on a listed
621	    // resource blocks the whole batch; a resource listed twice is free for
622	    // this request only when it is not held at all.
623	    let conflict = null;
624	    for (const resource of resources) {
625	      if (waitQueues.has(resource) || liveSlotCount(resource, now) > 0) {
626	        conflict = resource;
627	        break;
628	      }
629	    }
630	
631	    if (conflict !== null) {
632	      if (!wantsWait) {
633	        throw new LeaseTakenError(conflict, liveHolder(conflict, now));
634	      }
635	      return enqueueGroup(
636	        resources, ttlList, holder, now, waitMs, false,
637	      ).ticket;
638	    }
639	
640	    return commitDirectGrants(resources, ttlList, holder, now);
641	  }
642	
643	  function validateWait(waitMs) {
644	    const wantsWait = waitMs !== undefined && waitMs !== null;
645	    if (wantsWait && (!Number.isFinite(waitMs) || waitMs <= 0)) {
646	      throw new TypeError('waitMs must be a positive finite number');
647	    }
648	    return wantsWait;
649	  }
650	
651	  function acquire(resourceOrResources, holder, ttlMs = undefined, waitMs = undefined) {
652	    // Array input is the multi-resource form: same entry point, atomic rules.
653	    if (Array.isArray(resourceOrResources)) {
654	      return acquireAll(resourceOrResources, holder, ttlMs, waitMs);
655	    }
656	    const resource = resourceOrResources;
657	    const effectiveTtl = ttlMs === undefined ? defaultTtlMs : ttlMs;
658	    if (!Number.isFinite(effectiveTtl) || effectiveTtl <= 0) {
659	      throw new TypeError('ttlMs must be a positive finite number');
660	    }
661	    const wantsWait = validateWait(waitMs);
662	    const now = clock();
663	    purgeExpiredWaiters(now);
664	
665	    if (liveSlotCount(resource, now) > 0 || waitQueues.has(resource)) {
666	      if (!wantsWait) {
667	        throw new LeaseTakenError(resource, liveHolder(resource, now));
668	      }
669	      // Occupied or reserved: take a place in line instead of throwing. The
670	      // resource does not change hands just because a waiter showed up.
671	      return enqueueGroup(
672	        [resource], [effectiveTtl], holder, now, waitMs, true,
673	      ).ticket;
674	    }
675	
676	    const [granted] = commitDirectGrants(
677	      [resource], [effectiveTtl], holder, now,
678	    );
679	    return granted;
680	  }
681	
682	  function renew(token) {
683	    const lease = leases.get(token);
684	    if (lease === undefined || lease.legacy) {
685	      return false;
686	    }
687	    const now = clock();
688	    if (lease.expiresAt <= now) {
689	      return false;
690	    }
691	    purgeExpiredWaiters(now);
692	    const expiresAt = now + lease.ttlMs;
693	    appendEvent({ v: LOG_VERSION, type: 'renew', at: now, token, expiresAt });
694	
695	    lease.expiresAt = expiresAt;
696	    lease.heapSeq += 1;
697	    enqueue(token, lease);
698	    counters.renewed += 1;
699	    return true;
700	  }
701	
702	  function release(token) {
703	    const lease = leases.get(token);
704	    if (lease === undefined || lease.legacy) {
705	      return false;
706	    }
707	    const now = clock();
708	    if (lease.expiresAt <= now) {
709	      return false;
710	    }
711	    purgeExpiredWaiters(now);
712	
713	    // The freed resource goes to the requests at the head of its queue; a
714	    // group only wakes when every copy it needs is free. All wakeup grants
715	    // ride in the same write as the release, so a failed log leaves the lease
716	    // and every queue untouched.
717	    const plans = planWakeups([{ resource: lease.resource, live: true }], now);
718	    const events = [{ v: LOG_VERSION, type: 'release', at: now, token }];
719	    for (const plan of plans) {
720	      for (const grant of plan.grants) {
721	        events.push(grant.event);
722	      }
723	    }
724	    appendEvents(events);
725	
726	    // The record comes off immediately; its queued node retires lazily.
727	    leases.delete(token);
728	    removeSlot(lease.resource, token);
729	    counters.released += 1;
730	    for (const plan of plans) {
731	      applyPlannedGrants(plan, now);
732	    }
733	    return true;
734	  }
735	
736	  // Cancelling only lands on a request that is still queued: an already
737	  // woken, expired or cancelled request reports false, as does an unknown id.
738	  function cancel(requestId) {
739	    purgeExpiredWaiters(clock());
740	    const group = pendingGroups.get(requestId);
741	    if (group === undefined) {
742	      return false;
743	    }
744	    detachGroup(group);
745	    group.ticket.status = 'cancelled';
746	    return true;
747	  }
748	
749	  function sweep(now = clock()) {
750	    purgeExpiredWaiters(now);
751	    const due = [];
752	    while (expiryQueue.size > 0) {
753	      const node = expiryQueue.peek();
754	      if (node.expiresAt > now) {
755	        break;
756	      }
757	      expiryQueue.pop();
758	      const lease = leases.get(node.token);
759	      if (lease === undefined || lease.heapSeq !== node.heapSeq) {
760	        // Retired node: release, retake or renewal already superseded it.
761	        continue;
762	      }
763	      due.push(node);
764	    }
765	
766	    if (due.length === 0) {
767	      return [];
768	    }
769	
770	    // Every due node still carries the current lease record (retired nodes
771	    // were filtered above) and a current lease always occupies its resource.
772	    const reclaimable = due;
773	
774	    // Reclaimed resources are handed to the head requests of their queues in
775	    // the same expiry order the reclaim happens; every wakeup grant rides
776	    // along in the same log write, so a failed append rolls everything back.
777	    const events = [{
778	      v: LOG_VERSION,
779	      type: 'reclaim',
780	      at: now,
781	      items: reclaimable.map((node) => ({
782	        token: node.token,
783	        resource: leases.get(node.token).resource,
784	      })),
785	    }];
786	    const plans = planWakeups(
787	      reclaimable.map((node) => ({
788	        resource: leases.get(node.token).resource,
789	        live: false,
790	      })),
791	      now,
792	    );
793	    for (const plan of plans) {
794	      for (const grant of plan.grants) {
795	        events.push(grant.event);
796	      }
797	    }
798	
799	    try {
800	      appendEvents(events);
801	    } catch (error) {
802	      // The write never happened: put the popped nodes back so the queue is
803	      // byte-for-byte the same as before the call.
804	      for (const node of due) {
805	        expiryQueue.push(node);
806	      }
807	      throw error;
808	    }
809	
810	    const freed = [];
811	    for (const node of reclaimable) {
812	      const lease = leases.get(node.token);
813	      leases.delete(node.token);
814	      if (removeSlot(lease.resource, node.token)) {
815	        counters.reclaimed += 1;
816	        freed.push(lease.resource);
817	      }
818	    }
819	    for (const plan of plans) {
820	      applyPlannedGrants(plan, now);
821	    }
822	    return freed;
823	  }
824	
825	  function holder(resource) {
826	    const now = clock();
827	    purgeExpiredWaiters(now);
828	    return liveHolder(resource, now);
829	  }
830	
831	  function stats() {
832	    let live = 0;
833	    const now = clock();
834	    purgeExpiredWaiters(now);
835	    for (const list of slots.values()) {
836	      for (const token of list) {
837	        if (isLive(leases.get(token), now)) {
838	          live += 1;
839	        }
840	      }
841	    }
842	    return {
843	      granted: counters.granted,
844	      renewed: counters.renewed,
845	      released: counters.released,
846	      reclaimed: counters.reclaimed,
847	      live,
848	    };
849	  }
850	
851	  // Credentials of the atomic batch currently being replayed: a batch takes
852	  // over a resource as one unit, so its own earlier credentials must not be
853	  // treated as the stale lease it replaces.
854	  let replayBatchId = null;
855	  let replayBatchTokens = new Set();
856	  // Highest batch number seen in the log, so ids minted after a restart can
857	  // never collide with an earlier process's batches.
858	  let replayMaxBatchSeq = 0;
859	
860	  replay();
861	  batchSequence = Math.max(batchSequence, replayMaxBatchSeq);
862	
863	  return {
864	    acquire,
865	    acquireAll,
866	    acquireGroup: acquireAll,
867	    acquireMany: acquireAll,
868	    renew,
869	    release,
870	    sweep,
871	    holder,
872	    stats,
873	    cancel,
874	  };
875	
876	  function replay() {
877	    if (logPath === null) {
878	      return;
879	    }
880	
881	    let text;
882	    try {
883	      text = fs.readFileSync(logPath, 'utf8');
884	    } catch (cause) {
885	      if (cause.code === 'ENOENT') {
886	        // No log yet: start from an empty registry.
887	        return;
888	      }
889	      throw new LogFileError(
890	        `failed to read lease log at ${logPath}`,
891	        cause,
892	      );
893	    }
894	
895	    const lines = text.split('\n');
896	    for (let i = 0; i < lines.length; i += 1) {
897	      const line = lines[i];
898	      if (line.trim() === '') {
899	        continue;
900	      }
901	      let event;
902	      try {
903	        event = JSON.parse(line);
904	      } catch (cause) {
905	        throw new LogFileError(
906	          `corrupt lease log entry on line ${i + 1} of ${logPath}`,
907	          cause,
908	        );
909	      }
910	      replayEvent(event, i + 1);
911	    }
912	  }
913	
914	  function replayEvent(event, lineNumber) {
915	    if (event === null || typeof event !== 'object' || event.v !== LOG_VERSION) {
916	      throw new LogFileError(
917	        `unrecognized lease log version on line ${lineNumber} of ${logPath}`,
918	      );
919	    }
920	
921	    switch (event.type) {
922	      case 'acquire': {
923	        if (
924	          typeof event.token !== 'string' ||
925	          !Number.isFinite(event.ttlMs) ||
926	          !Number.isFinite(event.expiresAt)
927	        ) {
928	          throw new LogFileError(
929	            `corrupt acquire entry on line ${lineNumber} of ${logPath}`,
930	          );
931	        }
932	        // Credentials minted together for one atomic batch superseded any
933	        // expired, unswept lease on the resource as one unit: only slots held
934	        // by a different batch count as the stale lease being retaken.
935	        if (event.batch !== undefined && event.batch !== null) {
936	          const logged = /^batch-[^-]+-(\d+)$/.exec(String(event.batch));
937	          if (logged !== null) {
938	            replayMaxBatchSeq = Math.max(
939	              replayMaxBatchSeq,
940	              Number(logged[1]),
941	            );
942	          }
943	          if (event.batch !== replayBatchId) {
944	            replayBatchId = event.batch;
945	            replayBatchTokens = new Set();
946	          }
947	        } else {
948	          replayBatchId = null;
949	          replayBatchTokens = new Set();
950	        }
951	        const occupantTokens = slots.get(event.resource);
952	        if (occupantTokens !== undefined) {
953	          for (const oldToken of [...occupantTokens]) {
954	            if (!replayBatchTokens.has(oldToken)) {
955	              leases.delete(oldToken);
956	              removeSlot(event.resource, oldToken);
957	            }
958	          }
959	        }
960	        const lease = {
961	          resource: event.resource,
962	          holder: event.holder,
963	          expiresAt: event.expiresAt,
964	          ttlMs: event.ttlMs,
965	          // Credentials issued before this process started are void: the
966	          // lease keeps occupying the resource, but its token cannot
967	          // renew or release it.
968	          legacy: true,
969	          heapSeq: 0,
970	          batch: event.batch ?? null,
971	        };
972	        leases.set(event.token, lease);
973	        addSlot(event.resource, event.token);
974	        replayBatchTokens.add(event.token);
975	        knownTokens.add(event.token);
976	        enqueue(event.token, lease);
977	        counters.granted += 1;
978	        break;
979	      }
980	      case 'renew': {
981	        const lease = leases.get(event.token);
982	        if (
983	          typeof event.token !== 'string' ||
984	          !Number.isFinite(event.expiresAt)
985	        ) {
986	          throw new LogFileError(
987	            `corrupt renew entry on line ${lineNumber} of ${logPath}`,
988	          );
989	        }
990	        if (lease !== undefined) {
991	          lease.expiresAt = event.expiresAt;
992	          lease.heapSeq += 1;
993	          enqueue(event.token, lease);
994	        }
995	        counters.renewed += 1;
996	        break;
997	      }
998	      case 'release': {
999	        if (typeof event.token !== 'string') {
1000	          throw new LogFileError(
1001	            `corrupt release entry on line ${lineNumber} of ${logPath}`,
1002	          );
1003	        }
1004	        const lease = leases.get(event.token);
1005	        if (lease !== undefined) {
1006	          leases.delete(event.token);
1007	          removeSlot(lease.resource, event.token);
1008	        }
1009	        counters.released += 1;
1010	        break;
1011	      }
1012	      case 'reclaim': {
1013	        if (!Array.isArray(event.items)) {
1014	          throw new LogFileError(
1015	            `corrupt reclaim entry on line ${lineNumber} of ${logPath}`,
1016	          );
1017	        }
1018	        for (const item of event.items) {
1019	          if (item === null || typeof item !== 'object' ||
1020	              typeof item.token !== 'string') {
1021	            throw new LogFileError(
1022	              `corrupt reclaim entry on line ${lineNumber} of ${logPath}`,
1023	            );
1024	          }
1025	          const token = item.token;
1026	          const lease = leases.get(token);
1027	          if (lease !== undefined) {
1028	            leases.delete(token);
1029	            removeSlot(lease.resource, token);
1030	          }
1031	          counters.reclaimed += 1;
1032	        }
1033	        break;
1034	      }
1035	      default: {
1036	        throw new LogFileError(
1037	          `unknown lease log event type on line ${lineNumber} of ${logPath}`,
1038	        );
1039	      }
1040	    }
1041	  }
