42	test('acquire with a wait budget on an occupied resource queues a waiting result', () => {
43	  const clock = fakeClock(0);
44	  const registry = createRegistry({ ttlMs: 100, clock });
45	  registry.acquire('r', 'a');
46	
47	  const ticket = registry.acquire('r', 'b', 50, 1000);
48	
49	  assert.equal(ticket.status, 'waiting');
50	  assert.equal(ticket.resource, 'r');
51	  assert.equal(ticket.holder, 'b');
52	  assert.equal(typeof ticket.waitId, 'string');
53	  assert.equal('token' in ticket, false);
54	
55	  // Queueing moves no counter and does not change ownership.
56	  assert.equal(registry.holder('r'), 'a');
57	  assert.deepEqual(registry.stats(), {
58	    granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 1,
59	  });
60	
61	  // A non-waiting acquire still throws, even with a waiter queued.
62	  assert.throws(
63	    () => registry.acquire('r', 'c'),
64	    (e) => e instanceof LeaseTakenError && e.code === 'LEASE_TAKEN',
65	  );
66	  assert.equal(registry.holder('r'), 'a');
67	});
