69	test('wait budget must be a positive finite number when given', () => {
70	  const registry = createRegistry({ ttlMs: 100, clock: fakeClock(0) });
71	  registry.acquire('r', 'a');
72	  assert.throws(() => registry.acquire('r', 'b', 50, 0), TypeError);
73	  assert.throws(() => registry.acquire('r', 'b', 50, -1), TypeError);
74	  assert.throws(() => registry.acquire('r', 'b', 50, NaN), TypeError);
75	  assert.throws(() => registry.acquire('r', 'b', 50, Infinity), TypeError);
