import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

import { createRegistry, LogFileError } from './src/index.js';

function fakeClock(start = 0) {
  let now = start;
  const clock = () => now;
  clock.set = (v) => { now = v; };
  return clock;
}

const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lease-verify-'));
const lp = (n) => path.join(dir, `${n}.log`);

// 1. compact -> restart: holders, expiries, counters identical
{
  const p = lp('basic');
  const c = fakeClock(0);
  let r = createRegistry({ ttlMs: 100, clock: c, logPath: p });
  const keep = r.acquire('keep', 'h1', 100);
  const ren = r.acquire('ren', 'h2', 40);
  const freed = r.acquire('freed', 'h3', 100);
  r.acquire('gone', 'h4', 10);
  c.set(30);
  r.renew(ren.token);
  r.release(freed.token);
  c.set(50);
  r.sweep(); // reclaims 'gone'
  const before = r.stats();
  r.compact();
  // compacted log is a single snapshot line
  const lines = fs.readFileSync(p, 'utf8').trim().split('\n');
  assert.equal(lines.length, 1);
  assert.equal(JSON.parse(lines[0]).type, 'snapshot');

  r = createRegistry({ ttlMs: 100, clock: fakeClock(50), logPath: p });
  assert.equal(r.holder('keep'), 'h1');
  assert.equal(r.holder('ren'), 'h2');
  assert.equal(r.holder('freed'), null);
  assert.deepEqual(r.stats(), before);
  // pre-compaction credentials are void
  assert.equal(r.renew(keep.token), false);
  assert.equal(r.release(ren.token), false);
  // expiries survive: ren was renewed at 30 with ttl 40 -> expires 70
  assert.deepEqual(r.sweep(69), []);
  assert.deepEqual(r.sweep(70), ['ren']);
  assert.deepEqual(r.sweep(100), ['keep']);
  console.log('1 ok');
}

// 2. expired-but-unswept lease survives compaction; sweep afterwards matches
{
  const p = lp('unswept');
  const c = fakeClock(0);
  let r = createRegistry({ ttlMs: 100, clock: c, logPath: p });
  r.acquire('dead', 'h', 10);
  r.acquire('alive', 'h', 1000);
  c.set(50); // 'dead' expired, nobody swept
  r.compact();
  r = createRegistry({ ttlMs: 100, clock: fakeClock(50), logPath: p });
  assert.deepEqual(r.stats(), { granted: 2, renewed: 0, released: 0, reclaimed: 0, live: 1 });
  assert.deepEqual(r.sweep(), ['dead']);
  assert.equal(r.stats().reclaimed, 1);
  console.log('2 ok');
}

// 3. compact failure keeps the original log intact and throws a coded error
{
  const p = lp('fail');
  const r = createRegistry({ ttlMs: 100, clock: fakeClock(0), logPath: p });
  r.acquire('a', 'h');
  const before = fs.readFileSync(p, 'utf8');
  fs.renameSync(p, p + '.bak');
  fs.mkdirSync(p);
  try {
    assert.throws(() => r.compact(), (e) => e instanceof LogFileError && e.code === 'LOG_FILE_ERROR');
  } finally {
    fs.rmdirSync(p);
    fs.renameSync(p + '.bak', p);
  }
  assert.equal(fs.readFileSync(p, 'utf8'), before); // original log intact
  assert.equal(r.holder('a'), 'h'); // registry keeps working
  r.acquire('b', 'h');
  const r2 = createRegistry({ ttlMs: 100, clock: fakeClock(0), logPath: p });
  assert.equal(r2.stats().granted, 2);
  console.log('3 ok');
}

// 4. corrupt snapshot content / unknown snapshot version -> LogFileError
{
  const p = lp('bad-snap');
  fs.writeFileSync(p, '{"v":1,"type":"snapshot","leases":"nope","counters":{}}\n');
  assert.throws(
    () => createRegistry({ ttlMs: 10, clock: fakeClock(0), logPath: p }),
    (e) => e instanceof LogFileError && e.code === 'LOG_FILE_ERROR',
  );
  fs.writeFileSync(p, '{"v":99,"type":"snapshot","leases":[],"counters":{"granted":0,"renewed":0,"released":0,"reclaimed":0}}\n');
  assert.throws(
    () => createRegistry({ ttlMs: 10, clock: fakeClock(0), logPath: p }),
    (e) => e instanceof LogFileError && e.code === 'LOG_FILE_ERROR',
  );
  fs.writeFileSync(p, '{"v":1,"type":"snapshot","leases":[],"counters":{"granted":0,"renewed":0,"released":0}}\n');
  assert.throws(
    () => createRegistry({ ttlMs: 10, clock: fakeClock(0), logPath: p }),
    (e) => e instanceof LogFileError && e.code === 'LOG_FILE_ERROR',
  );
  console.log('4 ok');
}

// 5. half-line at the tail is ignored; complete lines stand; appends keep working
{
  const p = lp('half');
  const c = fakeClock(0);
  let r = createRegistry({ ttlMs: 100, clock: c, logPath: p });
  const a = r.acquire('a', 'h1', 100);
  const b = r.acquire('b', 'h2', 100);
  // simulate a crash mid-write: chop the last line in half
  const size = fs.statSync(p).size;
  fs.truncateSync(p, size - 10);
  r = createRegistry({ ttlMs: 100, clock: fakeClock(0), logPath: p });
  assert.equal(r.holder('a'), 'h1'); // complete line stands
  assert.equal(r.holder('b'), null); // half line never happened
  assert.equal(r.stats().granted, 1);
  // registry keeps working: new events do not fuse with the fragment
  r.acquire('b', 'h2', 100);
  const r3 = createRegistry({ ttlMs: 100, clock: fakeClock(0), logPath: p });
  assert.equal(r3.holder('a'), 'h1');
  assert.equal(r3.holder('b'), 'h2');
  assert.equal(r3.stats().granted, 2);
  assert.equal(r3.renew(a.token), false);
  assert.equal(r3.renew(b.token), false);
  console.log('5 ok');
}

// 6. compact after continued operation; group with repeated resource stays independent
{
  const p = lp('group');
  const c = fakeClock(0);
  let r = createRegistry({ ttlMs: 100, clock: c, logPath: p });
  const leases = r.acquireAll(['x', 'x'], 'h', [40, 60]);
  r.compact();
  // keep operating after compaction
  c.set(10);
  r.acquire('y', 'h2', 5);
  r = createRegistry({ ttlMs: 100, clock: fakeClock(10), logPath: p });
  assert.equal(r.holder('x'), 'h');
  assert.equal(r.holder('y'), 'h2');
  assert.deepEqual(r.stats(), { granted: 3, renewed: 0, released: 0, reclaimed: 0, live: 3 });
  // the two credentials on x expire independently; one reclaim frees nothing else
  assert.deepEqual(r.sweep(15), ['y']);
  assert.deepEqual(r.sweep(40), ['x']);
  assert.equal(r.holder('x'), 'h'); // second credential still holds
  assert.deepEqual(r.sweep(60), ['x']);
  assert.equal(r.holder('x'), null);
  assert.equal(r.stats().reclaimed, 3);
  console.log('6 ok');
}

// 7. many waiters: timeout cleanup order and no quadratic blow-up
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  r.acquire('r', 'owner');
  const N = 20000;
  const tickets = [];
  for (let i = 0; i < N; i += 1) {
    tickets.push(r.acquire('r', `w${i}`, 10, 500 + (i % 7)));
  }
  clock.set(1000);
  const t0 = Date.now();
  r.stats(); // observes all deadlines
  const elapsed = Date.now() - t0;
  assert.ok(tickets.every((t) => t.status === 'expired'));
  assert.equal(r.stats().granted, 1);
  // a second stats call is cheap (no rescan)
  const t1 = Date.now();
  for (let i = 0; i < 1000; i += 1) r.stats();
  const elapsed2 = Date.now() - t1;
  console.log(`7 ok (purge ${elapsed}ms, 1000 stats ${elapsed2}ms)`);
  assert.ok(elapsed < 2000, `purge too slow: ${elapsed}ms`);
  assert.ok(elapsed2 < 2000, `stats too slow: ${elapsed2}ms`);
}

// 8. expiry tie order preserved across compaction (renew re-orders the heap)
{
  const p = lp('ties');
  const c = fakeClock(0);
  let r = createRegistry({ ttlMs: 10, clock: c, logPath: p });
  const a = r.acquire('a', 'h', 10);
  r.acquire('b', 'h', 10);
  r.renew(a.token); // a re-enqueued after b, same expiresAt=10
  r.compact();
  r = createRegistry({ ttlMs: 10, clock: fakeClock(0), logPath: p });
  assert.deepEqual(r.sweep(10), ['b', 'a']); // b's node was older
  console.log('8 ok');
}

// 9. waiters do not survive restart; queue comes back empty
{
  const p = lp('waiters');
  const c = fakeClock(0);
  let r = createRegistry({ ttlMs: 100, clock: c, logPath: p });
  const lease = r.acquire('r', 'a');
  const ticket = r.acquire('r', 'b', 10, 1000);
  r.compact();
  r = createRegistry({ ttlMs: 100, clock: fakeClock(0), logPath: p });
  assert.equal(ticket.status, 'waiting'); // old process ticket untouched
  assert.equal(r.holder('r'), 'a');
  // no queued position blocks anything: freeing r leaves it free
  assert.equal(r.release(lease.token), false); // pre-restart credential void
  assert.deepEqual(r.sweep(100), ['r']);
  const next = r.acquire('r', 'c');
  assert.equal(next.holder, 'c');
  console.log('9 ok');
}

// 10. snapshot alias exists
{
  const r = createRegistry({ ttlMs: 10, clock: fakeClock(0) });
  assert.equal(typeof r.compact, 'function');
  assert.equal(typeof r.snapshot, 'function');
  r.compact(); // no-op with logPath null
  console.log('10 ok');
}

fs.rmSync(dir, { recursive: true, force: true });
console.log('all verification checks passed');

