  let r = createRegistry({ ttlMs: 100, clock: c, logPath: p });
  const leases = r.acquireAll(['x', 'x'], 'h', [40, 60]);
  r.compact();
  // keep operating after compaction
  c.set(10);
  r.acquire('y', 'h2', 5);
  r = createRegistry({ ttlMs: 100, clock: fakeClock(10), logPath: p });
  assert.equal(r.holder('x'), 'h');
  assert.equal(r.holder('y'), 'h2');
  assert.deepEqual(r.stats(), { granted: 3, renewed: 0, released: 0, reclaimed: 0, live: 3 });
  // the two credentials on x expire independently; one reclaim frees nothing else
  assert.deepEqual(r.sweep(15), ['y']);
  assert.deepEqual(r.sweep(40), ['x']);
  assert.equal(r.holder('x'), 'h'); // second credential still holds
  assert.deepEqual(r.sweep(60), ['x']);
  assert.equal(r.holder('x'), null);
  assert.equal(r.stats().reclaimed, 3);
  console.log('6 ok');
}

// 7. many waiters: timeout cleanup order and no quadratic blow-up
{
  const clock = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock });
  r.acquire('r', 'owner');
  const N = 20000;
  const tickets = [];
  for (let i = 0; i < N; i += 1) {
    tickets.push(r.acquire('r', `w${i}`, 10, 500 + (i % 7)));
  }
  clock.set(1000);
  const t0 = Date.now();
  r.stats(); // observes all deadlines
  const elapsed = Date.now() - t0;
  assert.ok(tickets.every((t) => t.status === 'expired'));
  assert.equal(r.stats().granted, 1);
  // a second stats call is cheap (no rescan)
  const t1 = Date.now();
  for (let i = 0; i < 1000; i += 1) r.stats();
  const elapsed2 = Date.now() - t1;
  console.log(`7 ok (purge ${elapsed}ms, 1000 stats ${elapsed2}ms)`);
  assert.ok(elapsed < 2000, `purge too slow: ${elapsed}ms`);
  assert.ok(elapsed2 < 2000, `stats too slow: ${elapsed2}ms`);
}

// 8. expiry tie order preserved across compaction (renew re-orders the heap)
{
  const p = lp('ties');
  const c = fakeClock(0);
  let r = createRegistry({ ttlMs: 10, clock: c, logPath: p });
  const a = r.acquire('a', 'h', 10);
  r.acquire('b', 'h', 10);
  r.renew(a.token); // a re-enqueued after b, same expiresAt=10
  r.compact();
  r = createRegistry({ ttlMs: 10, clock: fakeClock(0), logPath: p });
  assert.deepEqual(r.sweep(10), ['b', 'a']); // b's node was older
  console.log('8 ok');
}

// 9. waiters do not survive restart; queue comes back empty
{
  const p = lp('waiters');
  const c = fakeClock(0);
  let r = createRegistry({ ttlMs: 100, clock: c, logPath: p });
  const lease = r.acquire('r', 'a');
  const ticket = r.acquire('r', 'b', 10, 1000);
  r.compact();
  r = createRegistry({ ttlMs: 100, clock: fakeClock(0), logPath: p });
  assert.equal(ticket.status, 'waiting'); // old process ticket untouched
  assert.equal(r.holder('r'), 'a');
  // no queued position blocks anything: freeing r leaves it free
  assert.equal(r.release(lease.token), false); // pre-restart credential void
  assert.deepEqual(r.sweep(100), ['r']);
  const next = r.acquire('r', 'c');
  assert.equal(next.holder, 'c');
  console.log('9 ok');
}

// 10. snapshot alias exists
{
  const r = createRegistry({ ttlMs: 10, clock: fakeClock(0) });
  assert.equal(typeof r.compact, 'function');
  assert.equal(typeof r.snapshot, 'function');
  r.compact(); // no-op with logPath null
  console.log('10 ok');
}

