import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createRegistry, LogFileError } from './src/index.js';

const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lease-edge-'));
const lp = (n) => path.join(dir, n + '.log');
const clock = (() => { let t = 0; const c = () => t; c.set = (v) => { t = v; }; return c; })();

// compact with no log file yet -> creates a snapshot-only log
{
  const p = lp('fresh');
  const r = createRegistry({ ttlMs: 10, clock, logPath: p });
  r.compact();
  assert.equal(JSON.parse(fs.readFileSync(p, 'utf8').trim()).type, 'snapshot');
  const r2 = createRegistry({ ttlMs: 10, clock, logPath: p });
  assert.deepEqual(r2.stats(), { granted: 0, renewed: 0, released: 0, reclaimed: 0, live: 0 });
}

// renew after compact in the SAME process still works and replays after restart
{
  const p = lp('renew-after');
  const c2 = (() => { let t = 0; const c = () => t; c.set = (v) => { t = v; }; return c; })();
  let r = createRegistry({ ttlMs: 100, clock: c2, logPath: p });
  const l = r.acquire('r', 'h', 100);
  r.compact();
  c2.set(50);
  assert.equal(r.renew(l.token), true); // same process: credential still valid
  r = createRegistry({ ttlMs: 100, clock: (() => 50), logPath: p });
  assert.equal(r.holder('r'), 'h');
  assert.deepEqual(r.stats(), { granted: 1, renewed: 1, released: 0, reclaimed: 0, live: 1 });
  assert.deepEqual(r.sweep(149), []);
  assert.deepEqual(r.sweep(150), ['r']);
}

// double compaction
{
  const p = lp('twice');
  let r = createRegistry({ ttlMs: 100, clock, logPath: p });
  r.acquire('a', 'h', 100);
  r.compact();
  r.acquire('b', 'h', 100);
  r.compact();
  const lines = fs.readFileSync(p, 'utf8').trim().split('\n');
  assert.equal(lines.length, 1);
  r = createRegistry({ ttlMs: 100, clock, logPath: p });
  assert.deepEqual(r.stats(), { granted: 2, renewed: 0, released: 0, reclaimed: 0, live: 2 });
}

// whitespace-only tail is also a half-line
{
  const p = lp('ws');
  let r = createRegistry({ ttlMs: 100, clock, logPath: p });
  r.acquire('a', 'h', 100);
  fs.appendFileSync(p, '   ');
